package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.widget.*;import java.io.*;import java.nio.file.*;import java.text.SimpleDateFormat;import java.util.*;

/** SAF export/import of conversation history and project metadata, never credentials. */
public class DataBackupActivity extends ToolPageActivity {
 static final int EXPORT=810,IMPORT=811;volatile boolean busy;TextView status;DataBackupStore.Preview preview;String expectedRaw;long expectedRevision;File exportFile;
 public void onCreate(Bundle state){super.onCreate(state);page("备份与恢复","会话与项目元数据");show();}
 void show(){clear();ScrollView scroll=new ScrollView(this);LinearLayout content=new LinearLayout(this);content.setOrientation(1);scroll.addView(content);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));content.addView(label("会话历史备份",20));content.addView(label("包含会话、草稿和项目名称。当前版本不包含工作区文件、附件文件、技能、记忆、插件、MCP 配置、账号登录、API 密钥或运行环境。",14));content.addView(label("恢复会合并为新的只读历史，保留现有对话，不会重新执行任务，也不能直接续接原内核会话。备份文件包含你的聊天内容，请保存在可信位置。",14));content.addView(button("导出会话备份",()->chooseExport(null)));content.addView(button("选择备份并预览",this::chooseImport));status=label("",14);content.addView(status);
  if(preview!=null){content.addView(label("待导入："+preview.chats+" 个对话、"+preview.drafts+" 个草稿、"+preview.projects+" 个项目。\n不包含工作区和附件文件。",15));content.addView(button("确认合并为只读历史",this::confirmRestore));content.addView(button("取消本次导入",()->{preview=null;show();}));}
  try{File dir=new File(getFilesDir().getCanonicalFile(),"history-backups");File[] backups=dir.listFiles((d,name)->name.startsWith("before-restore-")&&name.endsWith(".zip"));if(backups!=null&&backups.length>0){Arrays.sort(backups,(a,b)->Long.compare(b.lastModified(),a.lastModified()));content.addView(label("恢复前快照",17));for(int i=0;i<Math.min(backups.length,5);i++){final File file=backups[i];content.addView(button("导出 "+new SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date(file.lastModified()))+" 的恢复前快照",()->chooseExport(file)));}}}catch(Exception ignored){}
 }
 void message(String value){runOnUiThread(()->{if(!isFinishing()&&status!=null)status.setText(value);});}
 interface Work{void run()throws Exception;}
 void work(Work action){if(busy)return;busy=true;message("处理中…");new Thread(()->{try{action.run();}catch(Exception e){message("操作失败："+e.getMessage());}finally{busy=false;}},"EvaHistoryBackup").start();}
 void chooseExport(File snapshot){if(busy)return;exportFile=snapshot;Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"Eva-history-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+".zip");try{startActivityForResult(intent,EXPORT);}catch(Exception e){message("无法打开系统保存位置："+e.getMessage());}}
 void chooseImport(){if(busy)return;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*").putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/zip","application/octet-stream","application/x-zip-compressed"});try{startActivityForResult(intent,IMPORT);}catch(Exception e){message("无法打开文件选择器："+e.getMessage());}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){message("已取消，没有修改数据");return;}final Uri uri=data.getData();if(request==EXPORT){final File snapshot=exportFile;work(()->{byte[] bytes;if(snapshot==null){DataBackupStore.idle(this);String raw;synchronized(ShellActivity.saveLock){raw=DataBackupStore.current(this);}bytes=DataBackupStore.encodeState(raw);}else{File expected=new File(getFilesDir().getCanonicalFile(),"history-backups").getCanonicalFile();if(!snapshot.getCanonicalFile().getParentFile().equals(expected)||Files.isSymbolicLink(snapshot.toPath())||snapshot.length()>DataBackupArchive.MAX_ZIP)throw new IOException("快照文件无效");bytes=Files.readAllBytes(snapshot.toPath());}try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("无法写入保存位置");out.write(bytes);out.flush();}message("备份已导出（不含工作区文件和账号凭据）");});}else if(request==IMPORT)work(()->{DataBackupStore.idle(this);DataBackupStore.Preview incoming;try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法读取所选文件");incoming=DataBackupStore.preview(in);}synchronized(ShellActivity.saveLock){expectedRaw=DataBackupStore.current(this);expectedRevision=ShellActivity.saveRevision.get();DataBackupStore.merge(new org.json.JSONObject(expectedRaw),incoming.state);}preview=incoming;runOnUiThread(()->{show();status.setText("预览完成，尚未修改当前数据");});});}
 void confirmRestore(){if(busy||preview==null)return;new AlertDialog.Builder(this).setTitle("确认恢复历史？").setMessage("将新建导入记录，现有对话不删除。导入记录只读，不恢复执行任务。系统会先在 Eva 私有目录保存当前会话快照；完成后将重新打开 Eva。").setNegativeButton("取消",null).setPositiveButton("合并并重新打开",(dialog,which)->work(()->{File backup=DataBackupStore.restore(this,preview,expectedRaw,expectedRevision);preview=null;runOnUiThread(()->{Toast.makeText(this,"已合并只读历史，恢复前快照已保存",Toast.LENGTH_LONG).show();startActivity(new Intent(this,ShellActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));finish();});})).show();}
 void leavePage(){if(busy){Toast.makeText(this,"正在处理，请稍候",Toast.LENGTH_SHORT).show();return;}super.leavePage();}
 public void onBackPressed(){leavePage();}
}
